<script setup lang="ts">
import {computed,reactive,watch} from 'vue'
import {useRoute,useRouter} from 'vue-router'
import {useI18n} from 'vue-i18n'
import {money} from '../format'
import {transactionQuery,availableTypes,summaryKeys} from '../transactions/query'
import {useTransactions} from '../transactions/useTransactions'
import WalletTransactionRow from '../transactions/WalletTransactionRow.vue'
const route=useRoute(),router=useRouter(),{t}=useI18n(),customer=route.meta.walletWorkspace==='customer'
const store=computed(()=>String(route.params.storeId)),query=computed(()=>route.query)
const {data,busy,error,refresh}=useTransactions(store,query,customer)
const filters=reactive<Record<string,string>>({targetStoreId:store.value,...transactionQuery(route.query,customer)})
watch(()=>route.query,q=>{for(const key of Object.keys(filters))delete filters[key];Object.assign(filters,{targetStoreId:store.value,...transactionQuery(q,customer)})})
const types=computed(()=>data.value?availableTypes(data.value.capabilities):['all'])
const stats=computed(()=>data.value?summaryKeys(data.value.capabilities):[])
const returnTo=computed(()=>route.fullPath)
function apply(){const next={...filters};delete next.cursor;if(next.period==='month'||next.period==='year'){delete next.startDate;delete next.endDate;if(next.period==='year')delete next.month}else{delete next.year;delete next.month;if(next.period==='today'){delete next.startDate;delete next.endDate}}void router.push({path:route.path,query:transactionQuery(next,customer)})}
function page(cursor?:string){const next=transactionQuery(route.query,customer);if(cursor)next.cursor=cursor;else delete next.cursor;void router.push({path:route.path,query:next})}
</script>
<template><section class="wallet-page-heading"><h2>{{t('wallet.transactions.title')}}</h2><button :disabled="busy" @click="refresh">{{t('wallet.refresh')}}</button></section>
<form class="wallet-form wallet-transaction-filters" @submit.prevent="apply"><label>{{t('wallet.transactions.period')}}<select v-model="filters.period"><option v-for="mode in ['month','year','range','today']" :key="mode" :value="mode">{{t(`wallet.transactions.${mode}`)}}</option></select></label><template v-if="filters.period==='month'||filters.period==='year'"><label>{{t('wallet.transactions.year')}}<input v-model="filters.year" type="number" min="1900" max="9999" :placeholder="data?.period.startDate.slice(0,4)"></label><label v-if="filters.period==='month'">{{t('wallet.transactions.month')}}<input v-model="filters.month" type="number" min="1" max="12" :placeholder="data?.period.startDate.slice(5,7)"></label></template><template v-if="filters.period==='range'"><label>{{t('wallet.transactions.startDate')}}<input v-model="filters.startDate" type="date" required></label><label>{{t('wallet.transactions.endDate')}}<input v-model="filters.endDate" type="date" required></label></template><label>{{t('wallet.transactions.type')}}<select v-model="filters.type"><option v-for="kind in types" :key="kind" :value="kind">{{t(`wallet.transactions.${kind}`)}}</option></select></label><label>{{t('wallet.transactions.status')}}<select v-model="filters.status"><option v-for="status in ['all','pending','completed','cancelled']" :key="status" :value="status">{{t(`wallet.transactions.${status}`)}}</option></select></label><label>{{t('wallet.transactions.reference')}}<input v-model.trim="filters.reference" maxlength="160"></label><label v-if="!customer">{{t('wallet.transactions.customerQuery')}}<input v-model.trim="filters.customerQuery" maxlength="100"></label><label>{{t('wallet.transactions.targetStoreId')}}<select v-model="filters.targetStoreId"><option :value="store">{{data?.stores.find(s=>s.id===store)?.name??store}}</option><option value="all">{{t('wallet.transactions.allStores')}}</option><option v-for="s in data?.stores.filter(s=>s.id!==store)??[]" :key="s.id" :value="s.id">{{s.name}}</option></select></label><button class="wallet-primary" :disabled="busy">{{t('wallet.transactions.search')}}</button></form>
<p v-if="error" class="wallet-error" role="alert">{{error}}</p><p v-if="busy" class="wallet-empty" role="status">{{t('wallet.loading')}}</p><template v-if="data"><p class="wallet-muted">{{t('wallet.transactions.normalized')}}: {{data.period.startDate}} – {{data.period.endDate}} · {{data.period.timeZone}}</p><section class="wallet-card"><h3>{{t('wallet.transactions.complete')}}</h3><dl class="wallet-transaction-stats"><template v-for="key in stats" :key="key"><dt>{{t(`wallet.transactions.${customer?({consumptionCents:'customerPayment',externalPaymentCents:'customerExternal',topupPrincipalCents:'customerTopup'} as Record<string,string>)[key]??key:key}`)}}</dt><dd>{{key.endsWith('Cents')?money(data.summary[key]??0)+' SGD':(data.summary[key]??0)+' '+t('wallet.transactions.points')}}</dd></template></dl></section><p>{{t('wallet.transactions.count',{count:data.totalCount})}}</p><p v-if="!data.items.length" class="wallet-empty">{{t('wallet.empty')}}</p><WalletTransactionRow v-for="row in data.items" :key="row.sourceType+row.id" :row="row" :customer="customer" :return-to="returnTo" /><div class="wallet-detail-actions"><button v-if="route.query.cursor" :disabled="busy" @click="router.back()">{{t('wallet.transactions.previous')}}</button><button v-if="data.nextCursor" :disabled="busy" @click="page(data.nextCursor)">{{t('wallet.transactions.next')}}</button></div></template></template>
